import{_ as t,o as r,c as a,a5 as s}from"./chunks/framework.QWVCgkrI.js";const o="/study/images/os/thread-scheduling.svg",f=JSON.parse('{"title":"Windowsのスレッドスケジューリング — 実行・待機・実行可能","description":"","frontmatter":{"title":"Windowsのスレッドスケジューリング — 実行・待機・実行可能","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"os","summary":"Windowsが次に動かすスレッドを選ぶ仕組みを、優先度とタイムスライスから追う。待機が終わってから実行を再開するまでの時間を区別し、WPAで調べる手順を示す。","aliases":["スレッドスケジューリング","スケジューラ","dispatcher","Ready","Running","Waiting","タイムスライス","quantum","プリエンプション","コンテキストスイッチ","アフィニティ","WPA","CPU Usage Precise","CPU Usage Sampled"],"verification":"Microsoft LearnのWindowsスケジューリングとWPAの資料に照合（2026-11-06）"}},"headers":[],"relativePath":"os/thread-scheduling.md","filePath":"os/thread-scheduling.md"}'),n={name:"os/thread-scheduling.md"};function d(i,e,c,h,l,p){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="windowsのスレッドスケジューリング-—-実行・待機・実行可能" tabindex="-1">Windowsのスレッドスケジューリング — 実行・待機・実行可能 <a class="header-anchor" href="#windowsのスレッドスケジューリング-—-実行・待機・実行可能" aria-label="Permalink to &quot;Windowsのスレッドスケジューリング — 実行・待機・実行可能&quot;">​</a></h1><p>ゲームのメインスレッドがワーカーの完了を待つとき、ワーカーが完了を通知してから、メインスレッドが実際に動き出すまでにも時間がかかることがあります。Windowsが論理プロセッサーに割り当てるのは、プロセスに属する個々の<strong>スレッド</strong>です。いつ条件待ちが終わり、いつCPUを使えたかを分けると、遅れた区間を特定できます。<a href="/study/os/process-startup.html">プロセスを起動してmainへ到達するまで</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/procthread/about-processes-and-threads" target="_blank" rel="noreferrer">Windowsのプロセスとスレッド</a></p><h2 id="実行可能になる時刻と、実行を再開する時刻" tabindex="-1">実行可能になる時刻と、実行を再開する時刻 <a class="header-anchor" href="#実行可能になる時刻と、実行を再開する時刻" aria-label="Permalink to &quot;実行可能になる時刻と、実行を再開する時刻&quot;">​</a></h2><p>動作中のスレッドを追うときは、まず次の三つの状態で考えます。実際のWindowsは内部でさらに細かい状態を持ちます。<a href="https://learn.microsoft.com/en-us/windows/win32/procthread/context-switches" target="_blank" rel="noreferrer">Windowsのコンテキストスイッチ</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/test/wpt/cpu-analysis" target="_blank" rel="noreferrer">WPAのCPU解析ガイド</a></p><table tabindex="0"><thead><tr><th>状態</th><th>そのスレッドで起きていること</th></tr></thead><tbody><tr><td>Running（実行中）</td><td>論理プロセッサーが命令を実行している。</td></tr><tr><td>Waiting（待機中）</td><td>イベントの通知、ロックの解放、入出力の完了など、待っている条件がまだ満たされていない。</td></tr><tr><td>Ready（実行可能）</td><td>命令の実行を続けられる。スケジューラが論理プロセッサーに割り当てるまで待つ。</td></tr></tbody></table><figure class="study-figure"><img src="'+o+'" alt="単一の論理CPUを使う説明用の例。対象スレッドは0〜2 msに実行し、2〜6 msは完了を待つ。6 msに実行可能になるが他のスレッドがCPUを使用中のため、9 msに実行を再開する。12 msまでの内訳は実行5 ms、条件待ち4 ms、実行可能状態3 ms。" width="760" height="324" loading="lazy"><figcaption>条件待ちの終了と、実行再開の時刻を分けて読みます。<a href="/study/images/os/thread-scheduling.svg" target="_blank" rel="noopener noreferrer">タイムラインを拡大</a></figcaption></figure><p>この例では、対象スレッドが <strong>2 ms</strong> に待機に入り、<strong>6 ms</strong> に待っていた条件が満たされます。ここで <code>Ready</code> に移りますが、対象が使える論理CPUは1つで、ほかのスレッドがその枠を使っています。CPUへの割り当てを受け、実行を再開するのは <strong>9 ms</strong> です。時刻は説明用で、図では切り替え処理や割り込みの時間を省いています。</p><p>0〜12 msの経過時間を分けると、<strong>CPUで実行した時間は5 ms</strong>（2 msと3 ms）、<strong>条件待ちは4 ms</strong>、<strong>実行可能になってから割り当てを受けるまでの遅れは3 ms</strong>です。条件待ちを短くするには完了を通知する側を追い、<code>Ready</code> の時間を短くするには同じCPUを使っていたスレッドや、対象が実行できるCPUの範囲を調べます。実行時間が長い場合は、対象スレッドがどの処理を実行していたかを調べます。<a href="https://learn.microsoft.com/en-us/windows-hardware/test/wpt/cpu-analysis" target="_blank" rel="noreferrer">MicrosoftのCPU解析ガイド</a></p><h2 id="優先度とタイムスライスで次のスレッドを選ぶ" tabindex="-1">優先度とタイムスライスで次のスレッドを選ぶ <a class="header-anchor" href="#優先度とタイムスライスで次のスレッドを選ぶ" aria-label="Permalink to &quot;優先度とタイムスライスで次のスレッドを選ぶ&quot;">​</a></h2><p>Windowsは、実行可能な候補から優先度の高いスレッドを選びます。スレッドがCPUを使う持ち時間を<strong>タイムスライス</strong>（クォンタム）と呼びます。同じ優先度のスレッドが複数いれば順に実行するのが基本です。持ち時間が尽きたときに同等以上の優先度の候補があれば、ほかのスレッドに切り替わります。より高い優先度のスレッドが実行可能になると、持ち時間の途中でも実行中のスレッドからCPUを取り上げることがあります。これが<strong>プリエンプション</strong>です。実行中のスレッドが自ら待機に入った場合も、別のスレッドにCPUを割り当てられます。<a href="https://learn.microsoft.com/en-us/windows/win32/procthread/scheduling-priorities" target="_blank" rel="noreferrer">Windowsのスケジューリング優先度</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/procthread/context-switches" target="_blank" rel="noreferrer">コンテキストスイッチが発生する条件</a></p><p>スレッドを切り替えるときは、直前のスレッドの実行位置やレジスターなどを保存し、次のスレッドの状態を復元します。これをコンテキストスイッチと呼びます。切り替え処理そのものに加え、別の作業でキャッシュが入れ替わり、再開後にキャッシュミスが増える場合もあります。短い仕事を大量に分けて待機と起床を繰り返す場面では、CPU時間や完了までの時間と合わせて切り替え回数を読みます。<a href="https://learn.microsoft.com/en-us/windows/win32/procthread/context-switches" target="_blank" rel="noreferrer">Microsoftのコンテキストスイッチ解説</a> · <a href="https://www.intel.com/content/www/us/en/docs/onetbb/developer-guide-api-reference/2022-1/appendix-a-costs-of-time-slicing.html" target="_blank" rel="noreferrer">Intelのタイムスライス費用の解説</a></p><p>同じスレッドがシステムコールでカーネルモードに入り、そのまま処理を続ける経路もあります。モードの切り替えはCPUの権限が変わることを指し、コンテキストスイッチはCPUを使うスレッドが交代することを指します。カーネルでの処理中に待機へ入れば、そのCPUで別のスレッドを実行できます。<a href="/study/os/system-calls-and-privilege.html">システムコールと特権モード</a> · <a href="/study/runtime/thread-synchronization.html">スレッドと同期</a></p><h2 id="複数のcpuがあるときは、割り当ての範囲も見る" tabindex="-1">複数のCPUがあるときは、割り当ての範囲も見る <a class="header-anchor" href="#複数のcpuがあるときは、割り当ての範囲も見る" aria-label="Permalink to &quot;複数のCPUがあるときは、割り当ての範囲も見る&quot;">​</a></h2><p>複数の論理プロセッサーがあれば、複数のスレッドを並行して実行できます。どの論理プロセッサーで実行できるかを制限する設定が<strong>アフィニティ</strong>です。CPU全体の使用率が低くても、処理の要となるスレッドを実行できる論理CPUが混み合い、<code>Ready</code> のまま待つことがあります。また、以前とは別のコアで再開すると、前のコアのキャッシュにあったデータを使いにくくなる場合があります。CPU全体の平均と合わせて、論理CPUごとの使用状況とスレッドの実行場所を読みます。<a href="https://learn.microsoft.com/en-us/windows-hardware/test/wpt/cpu-analysis#priority" target="_blank" rel="noreferrer">Microsoftの優先プロセッサーとアフィニティの解説</a> · <a href="https://www.intel.com/content/www/us/en/docs/vtune-profiler/cookbook/2024-2/os-thread-migration.html" target="_blank" rel="noreferrer">Intelのスレッド移動の解説</a></p><h2 id="wpaで長かった区間を探す" tabindex="-1">WPAで長かった区間を探す <a class="header-anchor" href="#wpaで長かった区間を探す" aria-label="Permalink to &quot;WPAで長かった区間を探す&quot;">​</a></h2><table tabindex="0"><thead><tr><th>表示</th><th>使うデータ</th><th>調べたいこと</th></tr></thead><tbody><tr><td>CPU Usage (Precise)</td><td>スレッドの切り替えや実行可能になった時刻のイベント</td><td>いつ実行し、何を待ち、再開までにどれだけ遅れたか。</td></tr><tr><td>CPU Usage (Sampled)</td><td>実行位置やコールスタックを定期的に採ったサンプル</td><td>実行中にCPU時間を多く使った関数はどれか。</td></tr></tbody></table><p>Windows Performance Recorder（WPR）で現象が起きた区間を記録し、Windows Performance Analyzer（WPA）で開きます。<code>CPU Usage (Precise)</code> で対象のプロセスとスレッドに絞り、<code>Waits (us)</code> と <code>Ready (us)</code> を比べます。待機が長い場合は、記録されたスタックやスレッドの依存関係から待ちの起点をたどります。実行可能な時間が長い場合は、その間に対象が実行できる論理CPUを誰が使っていたかを見ます。対象自身のCPU時間が長い場合は、同じ時間帯の <code>CPU Usage (Sampled)</code> でサンプルが集まった関数を調べます。<a href="https://learn.microsoft.com/en-us/troubleshoot/windows-server/support-tools/support-tools-xperf-wpa-wpr" target="_blank" rel="noreferrer">WPRとWPAの操作例</a> · <a href="https://learn.microsoft.com/en-us/windows-hardware/test/wpt/cpu-analysis#cpu-usage-precise-graph" target="_blank" rel="noreferrer">WPAのCPU Usageグラフ</a></p><p>ゲームのカクつきを調べる場合は、フレームが遅れた時刻を先に絞り、その区間のCPU側の状態を照合します。フレームが長かったときも、メインスレッドがCPUで仕事を続けていた場合と、ほかの仕事の完了を待っていた場合では、次に調べる場所が変わります。<a href="/study/graphics/optimization/frame-pacing.html">フレームタイムとフレームペーシング</a></p>',18)])])}const g=t(n,[["render",d]]);export{f as __pageData,g as default};
